 73	\begin{lemma}[Level of the diagonal line map]\label{lem:ld-dline-level}
 74		\lean{MIPStarRE.QPBT.isCondLinear_ldDLineCL}
 75		\leanok
 76		\uses{def:ld-question-distribution, def:cl-func}
